export interface ConnectorConfig {
  /** Notion integration token with write access to the target database. */
  notionToken: string;
  /** Notion database ID for the 'Signed' database. */
  notionDatabaseId: string;
  /** Pipedrive API token for fetching user details. */
  pipedriveApiToken: string;
  /** Base URL for Pipedrive API v2. Defaults to https://api.pipedrive.com/v2. */
  pipedriveApiBaseUrl?: string;
  /** Injected fetch for testing. */
  fetch?: typeof fetch;
}

export interface PipedriveWebhookPayload {
  data: {
    id: number;
    title: string;
    value: number;
    owner_id: number;
    won_time: string;
    status: string;
    close_time: string | null;
    [key: string]: unknown;
  };
  previous: unknown;
  meta: {
    event: string;
    entity: string;
    action: string;
    timestamp: string;
    [key: string]: unknown;
  };
}

export interface HandleResult {
  notionPageId: string;
  dealId: number;
}

async function fetchOwnerName(
  ownerId: number,
  config: ConnectorConfig,
): Promise<string> {
  const baseUrl = config.pipedriveApiBaseUrl ?? 'https://api.pipedrive.com/v2';
  const url = `${baseUrl}/users/${ownerId}`;
  const fetchFn = config.fetch ?? fetch;
  const response = await fetchFn(url, {
    method: 'GET',
    headers: {
      'Authorization': `Bearer ${config.pipedriveApiToken}`,
      'Accept': 'application/json',
    },
  });
  if (!response.ok) {
    throw new Error(`Pipedrive API error: ${response.status} ${response.statusText} for GET ${url}`);
  }
  const data = await response.json() as { data?: { name?: string } };
  if (!data.data?.name) {
    throw new Error(`Pipedrive user ${owner_id} has no name field`);
  }
  return data.data.name;
}

function formatDateForNotion(isoString: string): string {
  return isoString.split('T')[0];
}

export async function handle(
  payload: PipedriveWebhookPayload,
  config: ConnectorConfig,
): Promise<HandleResult> {
  const fetchFn = config.fetch ?? fetch;

  if (!payload.data?.title) throw new Error('Missing required field: data.title');
  if (payload.data.value === undefined || payload.data.value === null) throw new Error('Missing required field: data.value');
  if (!payload.data.owner_id) throw new Error('Missing required field: data.owner_id');
  if (!payload.data.won_time) throw new Error('Missing required field: data.won_time');
  if (payload.data.status !== 'won') throw new Error('Deal status is not won');

  const ownerName = await fetchOwnerName(payload.data.owner_id, config);
  const closeDate = formatDateForNotion(payload.data.won_time);

  const notionBody = {
    parent: { database_id: config.notionDatabaseId },
    properties: {
      Title: {
        title: [{ text: { content: payload.data.title } }],
      },
      'Deal Value': {
        number: payload.data.value,
      },
      Owner: {
        rich_text: [{ text: { content: ownerName } }],
      },
      'Close Date': {
        date: { start: closeDate },
      },
    },
  };

  const response = await fetchFn('https://api.notion.com/v1/pages', {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${config.notionToken}`,
      'Content-Type': 'application/json',
      'Notion-Version': '2022-06-28',
    },
    body: JSON.stringify(notionBody),
  });

  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(`Notion API error: ${response.status} ${response.statusText} for POST https://api.notion.com/v1/pages - ${errorText}`);
  }

  const result = await response.json() as { id: string };
  return { notionPageId: result.id, dealId: payload.data.id };
}

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { handle, ConnectorConfig, PipedriveWebhookPayload } from './connector';
import {
  SOURCE_EXAMPLE,
  contractFetch,
  fakeFetch,
  jsonResponse,
  TARGET_ENDPOINTS,
} from './fixtures';

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch();
    const config: ConnectorConfig = {
      notionToken: 'test-notion-token',
      notionDatabaseId: 'test-database-id',
      pipedriveApiToken: 'test-pipedrive-token',
      fetch,
    };
    const result = await handle(SOURCE_EXAMPLE as unknown as PipedriveWebhookPayload, config);
    expect(calls.length).toBeGreaterThan(0);
    expect(result.notionPageId).toBe('page-id-generated-by-notion');
    expect(result.dealId).toBe(8);
  });
});

describe('handle', () => {
  let baseConfig: ConnectorConfig;

  beforeEach(() => {
    baseConfig = {
      notionToken: 'test-notion-token',
      notionDatabaseId: 'test-database-id',
      pipedriveApiToken: 'test-pipedrive-token',
    };
  });

  it('happy path creates Notion page with correct field mapping', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/users/12415231')) {
        return jsonResponse({ data: { name: 'John Doe' } });
      }
      if (req.url === 'https://api.notion.com/v1/pages' && req.method === 'POST') {
        return jsonResponse({ id: 'new-page-id' }, 201);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    const payload: PipedriveWebhookPayload = {
      data: {
        id: 42,
        title: 'Test Deal',
        value: 5000,
        owner_id: 12415231,
        won_time: '2023-06-15T10:30:00Z',
        status: 'won',
        close_time: null,
      },
      previous: null,
      meta: { event: 'deal.won', entity: 'deal', action: 'change', timestamp: '2023-06-15T10:30:01Z' },
    };

    const result = await handle(payload, { ...baseConfig, fetch });

    expect(result.notionPageId).toBe('new-page-id');
    expect(result.dealId).toBe(42);
    expect(calls).toHaveLength(2);

    const pipedriveCall = calls[0];
    expect(pipedriveCall.method).toBe('GET');
    expect(pipedriveCall.url).toBe('https://api.pipedrive.com/v2/users/12415231');
    expect(pipedriveCall.headers.get('authorization')).toBe('Bearer test-pipedrive-token');

    const notionCall = calls[1];
    expect(notionCall.method).toBe('POST');
    expect(notionCall.url).toBe('https://api.notion.com/v1/pages');
    expect(notionCall.headers.get('authorization')).toBe('Bearer test-notion-token');
    expect(notionCall.headers.get('notion-version')).toBe('2022-06-28');

    const notionBody = notionCall.json as Record<string, unknown>;
    expect(notionBody.parent).toEqual({ database_id: 'test-database-id' });
    expect((notionBody.properties as Record<string, unknown>).Title).toEqual({
      title: [{ text: { content: 'Test Deal' } }],
    });
    expect((notionBody.properties as Record<string, unknown>)['Deal Value']).toEqual({ number: 5000 });
    expect((notionBody.properties as Record<string, unknown>).Owner).toEqual({
      rich_text: [{ text: { content: 'John Doe' } }],
    });
    expect((notionBody.properties as Record<string, unknown>)['Close Date']).toEqual({
      date: { start: '2023-06-15' },
    });
  });

  it('uses custom Pipedrive API base URL when provided', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://custom.pipedrive.com/v2/users/999') {
        return jsonResponse({ data: { name: 'Jane Smith' } });
      }
      if (req.url === 'https://api.notion.com/v1/pages') {
        return jsonResponse({ id: 'page-1' }, 201);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    const payload: PipedriveWebhookPayload = {
      data: {
        id: 1,
        title: 'Deal',
        value: 100,
        owner_id: 999,
        won_time: '2023-01-01T00:00:00Z',
        status: 'won',
        close_time: null,
      },
      previous: null,
      meta: { event: 'deal.won', entity: 'deal', action: 'change', timestamp: '2023-01-01T00:00:01Z' },
    };

    await handle(payload, { ...baseConfig, pipedriveApiBaseUrl: 'https://custom.pipedrive.com/v2', fetch });

    expect(calls[0].url).toBe('https://custom.pipedrive.com/v2/users/999');
  });

  it('throws when data.title is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const payload = {
      data: { value: 100, owner_id: 1, won_time: '2023-01-01T00:00:00Z', status: 'won' },
      previous: null,
      meta: { event: 'deal.won', entity: 'deal', action: 'change', timestamp: '2023-01-01T00:00:01Z' },
    } as unknown as PipedriveWebhookPayload;

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: data.title');
  });

  it('throws when data.value is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const payload = {
      data: { title: 'Deal', owner_id: 1, won_time: '2023-01-01T00:00:00Z', status: 'won' },
      previous: null,
      meta: { event: 'deal.won', entity: 'deal', action: 'change', timestamp: '2023-01-01T00:00:01Z' },
    } as unknown as PipedriveWebhookPayload;

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: data.value');
  });

  it('throws when data.owner_id is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const payload = {
      data: { title: 'Deal', value: 100, won_time: '2023-01-01T00:00:00Z', status: 'won' },
      previous: null,
      meta: { event: 'deal.won', entity: 'deal', action: 'change', timestamp: '2023-01-01T00:00:01Z' },
    } as unknown as PipedriveWebhookPayload;

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: data.owner_id');
  });

  it('throws when data.won_time is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const payload = {
      data: { title: 'Deal', value: 100, owner_id: 1, status: 'won' },
      previous: null,
      meta: { event: 'deal.won', entity: 'deal', action: 'change', timestamp: '2023-01-01T00:00:01Z' },
    } as unknown as PipedriveWebhookPayload;

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: data.won_time');
  });

  it('throws when deal status is not won', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const payload: PipedriveWebhookPayload = {
      data: { id: 1, title: 'Deal', value: 100, owner_id: 1, won_time: '2023-01-01T00:00:00Z', status: 'open', close_time: null },
      previous: null,
      meta: { event: 'deal.changed', entity: 'deal', action: 'change', timestamp: '2023-01-01T00:00:01Z' },
    };

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Deal status is not won');
  });

  it('throws on Pipedrive API non-2xx response', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/users/')) {
        return jsonResponse({ error: 'unauthorized' }, 401);
      }
      return jsonResponse({}, 200);
    });

    const payload: PipedriveWebhookPayload = {
      data: { id: 1, title: 'Deal', value: 100, owner_id: 1, won_time: '2023-01-01T00:00:00Z', status: 'won', close_time: null },
      previous: null,
      meta: { event: 'deal.won', entity: 'deal', action: 'change', timestamp: '2023-01-01T00:00:01Z' },
    };

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Pipedrive API error: 401 Unauthorized');
    expect(calls).toHaveLength(1);
  });

  it('throws when Pipedrive user has no name', async () => {
    const { fetch } = fakeFetch((req) => {
      if (req.url.includes('/users/')) {
        return jsonResponse({ data: {} });
      }
      return jsonResponse({}, 200);
    });

    const payload: PipedriveWebhookPayload = {
      data: { id: 1, title: 'Deal', value: 100, owner_id: 1, won_time: '2023-01-01T00:00:00Z', status: 'won', close_time: null },
      previous: null,
      meta: { event: 'deal.won', entity: 'deal', action: 'change', timestamp: '2023-01-01T00:00:01Z' },
    };

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Pipedrive user 1 has no name field');
  });

  it('throws on Notion API non-2xx response', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/users/')) {
        return jsonResponse({ data: { name: 'John' } });
      }
      if (req.url === 'https://api.notion.com/v1/pages') {
        return jsonResponse({ error: 'invalid database' }, 400);
      }
      return jsonResponse({}, 404);
    });

    const payload: PipedriveWebhookPayload = {
      data: { id: 1, title: 'Deal', value: 100, owner_id: 1, won_time: '2023-01-01T00:00:00Z', status: 'won', close_time: null },
      previous: null,
      meta: { event: 'deal.won', entity: 'deal', action: 'change', timestamp: '2023-01-01T00:00:01Z' },
    };

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Notion API error: 400 Bad Request');
    expect(calls).toHaveLength(2);
  });
});

